with base as (select id, store_id, order_date, status, amount, discount, shipping_fee, upper(status) status_upper, coalesce(channel, 'UNKNOWN') channel_clean from orders where order_date >= date '2023-06-05' and store_id is not null) select p.city, src.status, count(*) as cnt, min(src.discount) as min_discount, grouping_id() as level_id from base src inner join stores p on src.store_id = p.id group by grouping sets ((p.city, src.status), (p.city), ());
